import unittest
import json
from unittest.mock import MagicMock

class LocalStorageMock:
    def __init__(self):
        self.store = {}
    def getItem(self, key):
        return self.store.get(key)
    def setItem(self, key, value):
        self.store[key] = value

class TestStepTracker(unittest.TestCase):
    def setUp(self):
        self.storage = LocalStorageMock()

    def test_save_valid_steps(self):
        steps = 5000
        records = []
        records.append({'date': '2023-10-01', 'step_count': steps})
        self.storage.setItem('steps', json.dumps(records))

        stored = json.loads(self.storage.getItem('steps'))
        self.assertEqual(len(stored), 1)
        self.assertEqual(stored[0]['step_count'], 5000)

    def test_invalid_input_validation(self):
        def validate(val):
            try:
                num = int(val)
                return num >= 0
            except:
                return False

        self.assertFalse(validate(-100))
        self.assertFalse(validate('abc'))
        self.assertTrue(validate(1000))

    def test_suggestion_engine_calculation(self):
        records = [{'step_count': 1000} for _ in range(7)]
        total = sum(r['step_count'] for r in records)
        avg = total / 7
        self.assertEqual(avg, 1000)

    def test_suggestion_engine_insufficient_data(self):
        records = [{'step_count': 1000} for _ in range(3)]
        self.assertTrue(len(records) < 7)
        suggestion = 'Log more steps to get a 7-day average suggestion.'
        self.assertEqual(suggestion, 'Log more steps to get a 7-day average suggestion.')

if __name__ == '__main__':
    unittest.main()
